function eventOf(entry: ThreadEntry, readers: TurnReaders): TurnEvent | undefined {
  // A quotation is not an event, whatever the quoted text carries: the words are the
  // removed author's, and the notice quoting them is the machinery preserving them.
  // Read before the ending, because the quoted text may carry a tag (quoted text is
  // verbatim and can quote anything) and an ending read first would take the notice
  // for the turn the quoted text names.
  if (entry.quoted) return undefined;
  const ending = readers.ending(entry.body);
  if (ending !== "") return ending;
  if (readers.requestedAgent(entry.body) !== "") return "asked";
  return undefined;
}
```

