```ts
/** Ceiling on the preserved text, so the notice stays under GitHub's 65,536-character limit on a comment body. */
const MAX_PRESERVED_CHARS = 30_000;

/**
 * A code fence one run longer than the longest run of backticks in `text`.
 *
 * The fence is what keeps the quoted text verbatim. A body that itself contains a
 * fence -- somebody's own code block, which is exactly the thing worth preserving --
 * closes an ordinary ``` fence early, and everything after it leaves the block and is
 * read as this notice's speech. One longer than the longest run in the text closes
 * last. The floor is three: the ordinary fence, for a body with none.
 */
function fenceFor(text: string): string {
  let longest = 0;
  for (const run of text.match(/`+/g) ?? []) longest = Math.max(longest, run.length);
  return "`".repeat(Math.max(3, longest + 1));
}

/**
 * The part of the notice that carries the removed comment's text, or nothing.
 *
 * Quoted only when the comment was actually deleted -- while it is still on the page
 * the notice would be quoting it a second time -- and its body was read back before
 * the delete. A read that failed is said, not papered over: presenting the notice as
 * complete when the text is gone would be the loss the notice exists to prevent,
 * wearing a message that claims otherwise. The deletion itself is not held back by a
 * failed read -- stopping the race is the guard's job, and it outranks the preservation.
 */
function preservedSection(deleted: boolean, couldNotRead: boolean, original: string): string {
  if (!deleted) return "";
  if (couldNotRead) {
    return "The text of that comment could not be read back before it was removed, so it is not preserved here.";
  }
  if (original === "") return "";
  const truncated = original.length > MAX_PRESERVED_CHARS;
  const kept = truncated ? original.slice(0, MAX_PRESERVED_CHARS) : original;
  const fence = fenceFor(kept);
  const note = truncated
    ? `The comment was longer than ${MAX_PRESERVED_CHARS.toLocaleString("en-US")} characters; the rest is not preserved here.`
    : "";
  return [
    "<details><summary>Your comment, as you wrote it</summary>",
    "",
    fence,
    kept,
    fence,
    ...(note ? ["", note] : []),
    "",
    "</details>",
  ].join("\n");
}
```

